import{_ as o,c as a,o as r,ae as t}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy-policy.md","filePath":"guide/privacy-policy.md","lastUpdated":1795170900000}'),i={name:"guide/privacy-policy.md"};function s(n,e,c,l,d,u){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>What Persim collects and what stays on your device.</p><h2 id="no-account-no-cloud-profile" tabindex="-1">No account, no cloud profile <a class="header-anchor" href="#no-account-no-cloud-profile" aria-label="Permalink to &quot;No account, no cloud profile&quot;">​</a></h2><p>Persim does not ask you to sign in and does not create an online account for you. Your history, bookmarks, open tabs, downloads and cookies are saved on your Mac.</p><h2 id="information-used-to-show-pages" tabindex="-1">Information used to show pages <a class="header-anchor" href="#information-used-to-show-pages" aria-label="Permalink to &quot;Information used to show pages&quot;">​</a></h2><p>Like any browser, Persim sends the addresses you visit to the websites you open. Persim itself does not upload your browsing history to a server.</p><h2 id="network-features-you-can-turn-on" tabindex="-1">Network features you can turn on <a class="header-anchor" href="#network-features-you-can-turn-on" aria-label="Permalink to &quot;Network features you can turn on&quot;">​</a></h2><ul><li>Ad-blocking subscriptions refresh their rule lists over the network. If an update fails, the saved list keeps working.</li><li>User scripts and files you download are fetched only when you ask for them.</li><li>Search suggestions come from your chosen search engine when you type in the address bar.</li></ul><h2 id="local-permissions" tabindex="-1">Local permissions <a class="header-anchor" href="#local-permissions" aria-label="Permalink to &quot;Local permissions&quot;">​</a></h2><p>Camera, microphone and file access are remembered per site and can be changed in Settings. Location and notifications are controlled by macOS. A private window (⌘⇧N) does not add to your history or session.</p><h2 id="third-party-sites" tabindex="-1">Third-party sites <a class="header-anchor" href="#third-party-sites" aria-label="Permalink to &quot;Third-party sites&quot;">​</a></h2><p>Pages you visit are operated by others and follow their own privacy practices. Persim&#39;s built-in pages do not track you.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Privacy questions: <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',14)])])}const y=o(i,[["render",s]]);export{p as __pageData,y as default};
